package com.aistock.prediction.analysis;
import com.sun.net.httpserver.HttpServer;import com.fasterxml.jackson.databind.ObjectMapper;import java.net.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class AnalysisMarketClientTest {
 @Test void checksIdentityVersionRangeAndRejectsRedirectOrOversize()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var body=new String[]{""};var status=new int[]{200};server.createContext("/",e->{assertEquals("private",e.getRequestHeaders().getFirst("X-Service-Token"));byte[] bytes=body[0].getBytes(java.nio.charset.StandardCharsets.UTF_8);e.sendResponseHeaders(status[0],bytes.length);e.getResponseBody().write(bytes);e.close();});server.start();try{var m=new ObjectMapper();var c=new HttpAnalysisMarketClient("http://127.0.0.1:"+server.getAddress().getPort(),"private",m);var id=UUID.fromString("11111111-1111-4111-8111-111111111111");var from=LocalDate.parse("2026-07-07");var to=LocalDate.parse("2026-10-07");body[0]="{\"code\":\"OK\",\"data\":{\"instrumentId\":\"SH600030\",\"versionId\":\""+id+"\",\"requestedRange\":{\"from\":\"2026-07-07\",\"to\":\"2026-10-07\"}}}";assertEquals("SH600030",c.evidence("SH600030",from,to,id).path("instrumentId").asText());body[0]=body[0].replace("SH600030","SH600000");assertThrows(com.aistock.common.BusinessException.class,()->c.evidence("SH600030",from,to,id));status[0]=302;assertThrows(com.aistock.common.BusinessException.class,()->c.evidence("SH600030",from,to,id));status[0]=200;body[0]="x".repeat(524289);assertThrows(com.aistock.common.BusinessException.class,()->c.evidence("SH600030",from,to,id));}finally{server.stop(0);}}
}